        return sharedIndexInformerFor(apiTypeClass, apiListTypeClass, null, resyncPeriodInMillis, Utils.isResourceNamespaced(apiTypeClass));
    } catch (ClassCastException | UnsupportedOperationException | IllegalArgumentException | NullPointerException e) {
        throw new RuntimeException("Failed to create shared index informer for custom resource", e);
